    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                objects.append((r, c, grid[r][c]))

    colored = [(r, c, color) for r, c, color in objects if color not in (0, 3)]
    blank = [(r, c) for r, c, color in objects if color == 0]

    def own_arm(rr, cc, center):
        r, c, _ = center
        return (rr == r and abs(cc-c) == 1) or (cc == c and abs(rr-r) == 1)

    # Cast each colored center's four rays. Original 3s from other crosses
    # block rays; its own arms are transparent and remain visible.
    for center in colored:
        r, c, color = center
        for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                # Blank cross is an opaque barrier.
                if any((rr == br or cc == bc) for br, bc in blank):
                    break
                if grid[rr][cc] == 3 and not own_arm(rr, cc, center):
