    # original 3 markers that define the cross.
    for r, c in blank:
        for cc in range(w):
            if grid[r][cc] == 0:
                out[r][cc] = 0
        for rr in range(h):
            if grid[rr][c] == 0:
                out[rr][c] = 0

    # Repaint colored vertical rays after horizontal ones (vertical wins at
    # crossings), while preserving every original 3/cross marker.
    for center in colored:
        r, c, color = center
        for dr in (-1, 1):
            rr = r + dr
            while 0 <= rr < h:
